CONTEXTS=[
('Привезите груз к точке %s0: {reason}. Приёмная смена уже получила накладную и ждёт состав.',
 'Deliver the cargo to %s0: {reason}. The receiving shift has the manifest and is expecting your train.'),
('Пункт назначения — %s0. Здесь {reason}. Диспетчер выделил место для приёма этой партии.',
 'Your destination is %s0. Here, {reason}. Dispatch has reserved space to receive this shipment.'),
]

def summary(language,capacity=False):
    from xml.sax.saxutils import escape
    ru=language=='ru'
    def text(value):return '<TEXT>'+escape(value)+'</TEXT>'
    def field(label,value):
        return '<TRA bold="true"/>'+text(label+': ')+'<TRA bold="false"/>'+text(value)+'<PARA/>'
    parts=['<?xml version="1.0" encoding="UTF-16"?><RDL><PUSH/>']
    for label,value in ([('Груз','%s0'),('Отправитель','%s1'),('Получатель','%s2'),('Целевая система','%s3')] if ru else
                        [('Cargo','%s0'),('Shipper','%s1'),('Receiver','%s2'),('Destination system','%s3')]):parts.append(field(label,value))
    parts+=['<PARA/>',text('%!0'),'<PARA/><PARA/>']
    fields=([('Состав','%d0 вагонов · %d1 ед. груза'),('Маршрут','%d2 участков'),
             ('Награда','%d3 кр.'),('Утрачено контейнеров','%d5'),('К выплате','%d6 кр.'),
             ('Удержание за контейнер','%d4 кр., суммарно не больше награды'),('Ожидаемое время','%d7 мин.')] if ru else
            [('Train','%d0 wagons · %d1 cargo units'),('Route','%d2 legs'),
             ('Reward','%d3 credits'),('Containers lost','%d5'),('Payment due','%d6 credits'),
             ('Deduction per container','%d4 credits, total capped at the reward'),('Expected in','%d7 minutes')])
    parts.extend(field(label,value) for label,value in fields)
    if capacity:
        parts.append(field('Открытый максимум' if ru else 'Unlocked capacity',
                           '%d8 вагонов · %d9 ед. груза' if ru else '%d8 wagons · %d9 cargo units'))
    parts+=['<PARA/>',text('Таймер запускается при первом сцеплении. Опоздание не отменяет заказ и не уменьшает оплату.' if ru else
                          'The timer starts when you first couple the train. Late arrival does not cancel the order or reduce payment.'),
            '<PARA/><PARA/>',text('Подцепите состав у отправителя, доставьте груз получателю и отцепите вагоны в отмеченной точке.' if ru else
                                'Collect the train at the shipper, deliver the cargo to the receiver, and uncouple at the marked point.'),'<POP/></RDL>']
    return ''.join(parts)

SUMMARY=(summary('ru'),summary('en'))

def rows():
    result=[('description',238283,*SUMMARY),('timer',238284,'Груз ждут через','Cargo expected in'),
            ('overdue',238285,'Груз всё ещё ждут · +','Cargo still awaited · +'),
            ('loss',238286,'Груз утрачен: контейнеров %d0. К выплате: %d1 кр.',
             'Cargo lost: %d0 containers. Payment due: %d1 credits.'),
            ('pickup_from',238287,'Следуйте к точке %s0 за назначенным составом и подцепите его.',
             'Proceed to %s0 to collect and couple the assigned train.')]
    result.append(('description_capacity',238288,
        summary('ru',True),summary('en',True)))
    for index,(key,reasons) in enumerate(sorted(REASONS.items())):
        pairs=[r.split('~') for r in reasons.split('|')]
        assert len(pairs)==5 and all(len(p)==2 for p in pairs),key
        for variant in range(10):
            ru,en=pairs[variant%5];template=CONTEXTS[variant//5]
            result.append((f'brief_{key}_{variant+1:02}',FIRST_PROSE_ID+index*10+variant,
                           template[0].format(reason=ru),template[1].format(reason=en)))
    result.extend([('mission_title',238289,'Грузовые перевозки','Freight Transport'),
                   ('cargo_name',238290,'Грузовой состав','Freight Train')])
    return result

def description_ini():
    return '\n'.join('\n[CourierDescription]\ncommodity = comm_'+key+'\n'+
                     '\n'.join(f'text_ids = {FIRST_PROSE_ID+i*10+v}' for v in range(10))
                     for i,key in enumerate(sorted(REASONS)))+'\n'
